"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import { ArrowDownLeft, ArrowUpRight, Download, Plus, Sparkles, Wallet } from "lucide-react";
import { classifyTransaction } from "../packages/financial-engine/classification";
import { parseMpesaSms } from "../packages/transaction-parser/mpesa-parser";

type Kind = "INCOME" | "EXPENSE" | "TRANSFER";
type Account = { id: string; name: string; type: string; balance: number; reserved: number };
type Entry = { id: string; kind: Kind; amount: number; category: string; note: string; date: string; accountId: string };
type AppState = { accounts: Account[]; entries: Entry[]; budget: number; goal: number; saved: number };
const key = "pesapilot-v1", today = new Date().toISOString().slice(0, 10);
const seed: AppState = { accounts: [{ id: "mpesa", name: "M-Pesa", type: "Mobile money", balance: 8400, reserved: 1000 }, { id: "bank", name: "Bank account", type: "Bank", balance: 15200, reserved: 0 }], entries: [{ id: "1", kind: "INCOME", amount: 12000, category: "HELB", note: "HELB disbursement", date: today, accountId: "bank" }, { id: "2", kind: "EXPENSE", amount: 450, category: "FOOD", note: "Lunch", date: today, accountId: "mpesa" }, { id: "3", kind: "EXPENSE", amount: 180, category: "TRANSPORT", note: "Matatu", date: today, accountId: "mpesa" }], budget: 18000, goal: 5000, saved: 1200 };
const money = (value: number) => new Intl.NumberFormat("en-KE", { style: "currency", currency: "KES", maximumFractionDigits: 0 }).format(value);
const uid = () => `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;

export default function Home() {
  const [data, setData] = useState<AppState>(seed), [ready, setReady] = useState(false), [notice, setNotice] = useState(""), [tab, setTab] = useState<"overview" | "transactions" | "plan">("overview");
  const [form, setForm] = useState({ kind: "EXPENSE" as Kind, amount: "", category: "FOOD", note: "", accountId: "mpesa" });
  const [sms, setSms] = useState(""), [account, setAccount] = useState({ name: "", type: "Mobile money", balance: "" });
  useEffect(() => { const stored = localStorage.getItem(key); if (stored) try { setData(JSON.parse(stored)); } catch { localStorage.removeItem(key); } setReady(true); }, []);
  useEffect(() => { if (ready) localStorage.setItem(key, JSON.stringify(data)); }, [data, ready]);
  const update = (fn: (current: AppState) => AppState) => setData(fn);
  const metrics = useMemo(() => { const expense = data.entries.filter(e => e.kind === "EXPENSE").reduce((n, e) => n + e.amount, 0), income = data.entries.filter(e => e.kind === "INCOME").reduce((n, e) => n + e.amount, 0), total = data.accounts.reduce((n, a) => n + a.balance, 0), reserved = data.accounts.reduce((n, a) => n + a.reserved, 0); const categories = Object.entries(data.entries.filter(e => e.kind === "EXPENSE").reduce<Record<string, number>>((out, e) => { out[e.category] = (out[e.category] || 0) + e.amount; return out; }, {})).sort((a, b) => b[1] - a[1]); return { expense, income, total, reserved, safe: Math.max(0, total - reserved), categories, budgetLeft: data.budget - expense }; }, [data]);
  const addEntry = (event: FormEvent) => { event.preventDefault(); const amount = Number(form.amount); if (!amount || amount <= 0 || !form.accountId) return setNotice("Enter a positive amount and choose an account."); update(current => { const delta = form.kind === "INCOME" ? amount : form.kind === "EXPENSE" ? -amount : 0; return { ...current, accounts: current.accounts.map(a => a.id === form.accountId ? { ...a, balance: a.balance + delta } : a), entries: [{ id: uid(), ...form, amount, date: today }, ...current.entries] }; }); setForm({ ...form, amount: "", note: "" }); setNotice("Transaction saved and account balance updated."); };
  const importSms = () => { const parsed = parseMpesaSms(sms); if (!parsed) return setNotice("That doesn’t look like a supported M-Pesa message yet."); if (data.entries.some(e => e.note === parsed.rawMessageReference)) return setNotice("That M-Pesa message was already imported."); const kind: Kind = parsed.transactionType === "INCOME" ? "INCOME" : "EXPENSE", amount = parsed.amount / 100; update(current => ({ ...current, accounts: current.accounts.map(a => a.id === "mpesa" ? { ...a, balance: a.balance + (kind === "INCOME" ? amount : -amount) } : a), entries: [{ id: uid(), kind, amount, category: classifyTransaction(parsed.rawMessageReference, parsed.counterparty), note: parsed.rawMessageReference, date: parsed.transactionDate, accountId: "mpesa" }, ...current.entries] })); setSms(""); setNotice("M-Pesa transaction imported and categorised."); };
  const addAccount = (event: FormEvent) => { event.preventDefault(); const balance = Number(account.balance); if (!account.name || Number.isNaN(balance)) return setNotice("Add an account name and opening balance."); update(c => ({ ...c, accounts: [...c.accounts, { id: uid(), name: account.name, type: account.type, balance, reserved: 0 }] })); setAccount({ name: "", type: "Mobile money", balance: "" }); setNotice("Account added."); };
  const exportData = () => { const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }), href = URL.createObjectURL(blob), a = document.createElement("a"); a.href = href; a.download = `pesapilot-${today}.json`; a.click(); URL.revokeObjectURL(href); setNotice("Your private data export has downloaded."); };
  const reset = () => { localStorage.removeItem(key); setData(seed); setNotice("Demo data restored."); };
  return <main><header><div className="brand"><Wallet size={25} /> PesaPilot</div><nav>{(["overview", "transactions", "plan"] as const).map(item => <button key={item} className={tab === item ? "active" : ""} onClick={() => setTab(item)}>{item}</button>)}<button onClick={exportData} title="Export data"><Download size={18} /></button></nav></header><section className="hero"><div><span className="eyebrow">YOUR MONEY, CLEARLY</span><h1>Make every shilling count.</h1><p>A private, practical money cockpit for student life in Kenya.</p></div><div className="safe"><span>Safe to spend</span><strong>{money(metrics.safe)}</strong><small>after {money(metrics.reserved)} reserved</small></div></section>{notice && <div className="notice">{notice}<button onClick={() => setNotice("")}>×</button></div>}
  {tab === "overview" && <><section className="metrics"><Metric label="Total balance" value={money(metrics.total)} icon={<Wallet />} /><Metric label="Income" value={money(metrics.income)} icon={<ArrowDownLeft />} positive /><Metric label="Spent" value={money(metrics.expense)} icon={<ArrowUpRight />} /><Metric label="Budget left" value={money(metrics.budgetLeft)} icon={<Sparkles />} positive={metrics.budgetLeft >= 0} /></section><section className="grid"><article className="card"><h2>Spending by category</h2>{metrics.categories.length ? metrics.categories.map(([name, amount]) => <div className="bar" key={name}><div><span>{name}</span><b>{money(amount)}</b></div><i><em style={{ width: `${Math.min(100, amount / Math.max(metrics.expense, 1) * 100)}%` }} /></i></div>) : <Empty text="Your spending categories will appear here." />}</article><article className="card"><h2>Accounts</h2>{data.accounts.map(a => <div className="account" key={a.id}><div><b>{a.name}</b><small>{a.type}</small></div><strong>{money(a.balance)}</strong></div>)}<form className="inline-form" onSubmit={addAccount}><input placeholder="New account" value={account.name} onChange={e => setAccount({ ...account, name: e.target.value })} /><input aria-label="Opening balance" type="number" placeholder="Balance" value={account.balance} onChange={e => setAccount({ ...account, balance: e.target.value })} /><button className="primary"><Plus size={16} /> Add</button></form></article></section><section className="grid"><article className="card"><h2>Financial runway</h2><p className="large">{metrics.expense ? `${Math.floor(metrics.safe / (metrics.expense / Math.max(1, new Set(data.entries.map(e => e.date)).size)))} days` : "Building history"}</p><p className="muted">Based on your current available money and recorded spending.</p></article><article className="card"><h2>Savings goal</h2><div className="goal"><div><b>Emergency fund</b><span>{money(data.saved)} of {money(data.goal)}</span></div><i><em style={{ width: `${Math.min(100, data.saved / data.goal * 100)}%` }} /></i></div><button className="text-button" onClick={() => update(c => ({ ...c, saved: Math.min(c.goal, c.saved + 500) }))}>Add KSh 500 to goal</button></article></section></>}
  {tab === "transactions" && <><section className="workspace"><article className="card"><h2>Add transaction</h2><form className="form" onSubmit={addEntry}><label>Type<select value={form.kind} onChange={e => setForm({ ...form, kind: e.target.value as Kind })}><option>EXPENSE</option><option>INCOME</option><option>TRANSFER</option></select></label><label>Amount (KSh)<input required min="1" type="number" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} /></label><label>Category<input value={form.category} onChange={e => setForm({ ...form, category: e.target.value.toUpperCase() })} /></label><label>Account<select value={form.accountId} onChange={e => setForm({ ...form, accountId: e.target.value })}>{data.accounts.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select></label><label className="wide">Note<input value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} /></label><button className="primary wide">Save transaction</button></form></article><article className="card"><h2>Import M-Pesa SMS</h2><p className="muted">Paste a message such as “M-Pesa SMS: KES 500.00 sent to Cafe. Balance: KES 1200.00”.</p><textarea value={sms} onChange={e => setSms(e.target.value)} placeholder="Paste SMS here" /><button className="primary" onClick={importSms}>Parse and import</button></article></section><section className="card transaction-list"><h2>Recent transactions</h2>{data.entries.map(e => <div className="transaction" key={e.id}><span className={e.kind === "INCOME" ? "income-dot" : "expense-dot"}>{e.kind === "INCOME" ? "+" : "−"}</span><div><b>{e.note || e.category}</b><small>{e.category} · {e.date}</small></div><strong className={e.kind === "INCOME" ? "income" : ""}>{e.kind === "INCOME" ? "+" : "−"}{money(e.amount)}</strong></div>)}</section></>}
  {tab === "plan" && <section className="workspace"><article className="card"><h2>Monthly plan</h2><label>Monthly budget (KSh)<input type="number" value={data.budget} onChange={e => update(c => ({ ...c, budget: Number(e.target.value) || 0 }))} /></label><label>Emergency fund target (KSh)<input type="number" value={data.goal} onChange={e => update(c => ({ ...c, goal: Number(e.target.value) || 0 }))} /></label><p className="muted">Changes are saved only in this browser until you export them.</p></article><article className="card"><h2>Smart check-in</h2><p>{metrics.budgetLeft < 0 ? "You are over budget. Pause non-essential spending and review your largest category." : `You have ${money(metrics.budgetLeft)} remaining in your budget.`}</p><p>{metrics.safe < 1000 ? "Your safe-to-spend amount is low; keep the next few purchases essential." : "Your reserves are protected. Keep adding to your emergency fund."}</p><button className="text-button" onClick={reset}>Restore demo data</button></article></section>}<footer>Private by design · Stored in your browser · <button onClick={reset}>Reset demo</button></footer></main>;
}
function Metric({ label, value, icon, positive }: { label: string; value: string; icon: React.ReactNode; positive?: boolean }) { return <article className="metric"><span className={positive ? "metric-icon good" : "metric-icon"}>{icon}</span><small>{label}</small><strong>{value}</strong></article>; }
function Empty({ text }: { text: string }) { return <p className="muted empty">{text}</p>; }
